<?php
namespace Tests\Feature\Finance;
use App\Models\FeePrice; use App\Services\Finance\InvoiceCalculationService;
class TariffVersioningTest extends ModernFinanceCatalogTestCase { public function test_overlap_rejected_and_future_version_allowed_and_resolved():void{$fee=$this->fee();FeePrice::create($this->tariff($fee));$this->actingAs($this->user)->post(route('dashboard.finance.tariffs.store'),$this->tariff($fee,['amount'=>'1050.00','start_date'=>'2026-09-15','end_date'=>'2026-10-15']))->assertSessionHasErrors('start_date');$this->actingAs($this->user)->post(route('dashboard.finance.tariffs.store'),$this->tariff($fee,['amount'=>'1100.00','start_date'=>'2026-10-01','end_date'=>null]))->assertSessionHasNoErrors();$prices=FeePrice::orderBy('start_date')->get();$this->assertSame('expired',$prices[0]->status('2026-10-15'));$this->assertSame('current',$prices[1]->status('2026-10-15'));$this->assertSame('future',$prices[1]->status('2026-09-15'));$calc=app(InvoiceCalculationService::class);$this->assertSame('1000.00',$calc->calculate([['fee_id'=>$fee->id]],pricingDate:'2026-09-15',academicYearId:$this->year->id)['total_amount']);$this->assertSame('1100.00',$calc->calculate([['fee_id'=>$fee->id]],pricingDate:'2026-10-15',academicYearId:$this->year->id)['total_amount']);}}
